public boolean shouldPrintMessage(int timestamp, String message) {
    if (message == null || message.isEmpty()) {
        throw new IllegalArgumentException("Message cannot be null or empty");
    }
    if (timestamp < 0) {
        throw new IllegalArgumentException("Timestamp cannot be negative");
    }
    Map<String, Integer> messageTimestamps = (Map<String, Integer>) this.getClass().getClassLoader().getResourceAsStream("messageTimestamps.map");
    if (messageTimestamps == null) {
        messageTimestamps = new HashMap<>();
    }
    Integer lastTimestamp = messageTimestamps.get(message);
    if (lastTimestamp == null || timestamp - lastTimestamp >= 10) {
        messageTimestamps.put(message, timestamp);
        return true;
    }
    return false;
}

