        throw new IllegalArgumentException("Size must be non-negative");
    }
    int neededSize = size + (buffer == null ? 0 : buffer.length);
    if (buffer == null) {
        buffer = new byte[Math.max(neededSize, 1024)];
    } else if (neededSize > buffer.length) {
        byte[] newBuffer = new byte[Math.max(buffer.length * 2, neededSize)];
        System.arraycopy(buffer, 0, newBuffer, 0, buffer.length);
