private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    try {
        // Check if the descriptor is a method descriptor
        if (descriptor.charAt(0) == '(') {
            int end = descriptor.indexOf(')');
            if (end == -1) {
                throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
            }
            String argumentTypes = descriptor.substring(1, end);
            int index = 0;
            while (index < argumentTypes.length()) {
                char type = argumentTypes.charAt(index++);
                switch (type) {
                    case 'B': case 'C': case 'D': case 'F': case 'I': case 'S': case 'Z':
                        // Single slot types
                        popFromOutputFrameStack();
                        break;
                    case 'J': case 'D':
                        // Double slot types
                        popFromOutputFrameStack();
                        popFromOutputFrameStack();
                        break;
                    case 'L':
                        // Reference type
                        popFromOutputFrameStack();
                        while (argumentTypes.charAt(index) != ';') {
                            index++;
                        }
                        index++; // Move past ';'
                        break;
                    case '[':
                        // Array type
                        popFromOutputFrameStack();
                        // Skip array dimensions and type
                        while (argumentTypes.charAt(index) == '[') {
                            index++;
                        }
                        type = argumentTypes.charAt(index++);
                        if (type == 'L') {
                            while (argumentTypes.charAt(index) != ';') {
                                index++;
                            }
                            index++; // Move past ';'
                        }
                        break;
                    default:
                        throw new IllegalArgumentException("Invalid type character in descriptor: " + type);
                }
            }
        } else {
            // Descriptor is a single type
            switch (descriptor.charAt(0)) {
                case 'B': case 'C': case 'D': case 'F': case 'I': case 'S': case 'Z':
                    popFromOutputFrameStack();
                    break;
                case 'J': case 'D':
                    popFromOutputFrameStack();
                    popFromOutputFrameStack();
                    break;
                case 'L':
                    popFromOutputFrameStack();
                    // Skip the rest of the class descriptor
                    int index = 1;
                    while (descriptor.charAt(index) != ';') {
                        index++;
                    }
                    break;
                case '[':
                    popFromOutputFrameStack();
                    // Skip array dimensions and type
                    int index = 1;
                    while (descriptor.charAt(index) == '[') {
                        index++;
                    }
                    char type = descriptor.charAt(index);
                    if (type == 'L') {
                        index++;
                        while (descriptor.charAt(index) != ';') {
                            index++;
                        }
                    }
                    break;
                default:
                    throw new IllegalArgumentException("Invalid type character in descriptor: " + descriptor.charAt(0));
            }
        }
    } catch (StringIndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Invalid descriptor format", e);
    }
}

