        return false;
    }
    ListNodeImpl<E> prev = node.getPrevious();
    ListNodeImpl<E> next = node.getNext();
    if (prev == null) {
        // Node was the head
        if (next == null) {
            // Node was the only element in the list
            head = null;
            tail = null;
        } else {
            head = next;
            next.setPrevious(null);
        }
    } else if (next == null) {
        // Node was the tail
        prev.setNext(null);
        tail = prev;
    } else {
        // Node was in the middle
        prev.setNext(next);
        next.setPrevious(prev);
    }
    node.setPrevious(null);
    node.setNext(null);
    size--;
    return true;
}

