int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    try {
        while (bb.hasRemaining()) {
            int b = bb.get() & 0xFF;
            if ((b & 0x80) == 0) {
                // 1-byte character
                sb.append((char) b);
            } else if ((b & 0xE0) == 0xC0) {
                // 2-byte character
                if (bb.remaining() < 1) break;
                int b2 = bb.get() & 0xFF;
                sb.append((char) ((b & 0x1F) << 6 | (b2 & 0x3F)));
            } else if ((b & 0xF0) == 0xE0) {
                // 3-byte character
                if (bb.remaining() < 2) break;
                int b2 = bb.get() & 0xFF;
                int b3 = bb.get() & 0xFF;
                sb.append((char) ((b & 0x0F) << 12 | (b2 & 0x3F) << 6 | (b3 & 0x3F)));
            } else if ((b & 0xF8) == 0xF0) {
                // 4-byte character
                if (bb.remaining() < 3) break;
                int b2 = bb.get() & 0xFF;
                int b3 = bb.get() & 0xFF;
                int b4 = bb.get() & 0xFF;
                int codePoint = ((b & 0x07) << 18 | (b2 & 0x3F) << 12 | (b3 & 0x3F) << 6 | (b4 & 0x3F));
                sb.append(Character.toChars(codePoint));
            } else {
                // Invalid UTF-8 sequence
                break;
            }
        }
        return bb.position();
    } catch (Exception e) {
        // Handle unexpected issues, return current position
        return bb.position();
    }
}

