public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int len = str.length();
    int i = 0;
    while (i < len) {
        char c = str.charAt(i);
        if (c != '\\') {
            sb.append(c);
            i++;
        } else {
            if (i + 1 >= len) {
                throw new Exception("Invalid escape sequence");
            }
            char next = str.charAt(i + 1);
            switch (next) {
                case 't':
                    sb.append('\t');
                    break;
                case 'b':
                    sb.append('\b');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case 'u':
                    if (i + 5 >= len) {
                        throw new Exception("Invalid Unicode escape sequence");
                    }
                    String hex = str.substring(i + 2, i + 6);
                    try {
                        int value = Integer.parseInt(hex, 16);
                        sb.append((char) value);
                        i += 5;
                    } catch (NumberFormatException e) {
                        throw new Exception("Invalid Unicode escape sequence: " + hex);
                    }
                    break;
                default:
                    throw new Exception("Invalid escape sequence: \\" + next);
            }
            i += 2;
        }
    }
    return sb.toString();
}

