public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath must not be null");
    }

    // Normalize the paths by removing trailing slashes
    if (path.endsWith("/")) {
        path = path.substring(0, path.length() - 1);
    }
    if (relativePath.startsWith("/")) {
        relativePath = relativePath.substring(1);
    }

    // Split the relative path into segments
    String[] segments = relativePath.split("/");

    // Use a stack to build the final path
    Stack<String> pathStack = new Stack<>();
    for (String segment : path.split("/")) {
        pathStack.push(segment);
    }

    for (String segment : segments) {
        if (segment.equals("..")) {
            if (!pathStack.isEmpty()) {
                pathStack.pop(); // Move up one directory
            }
        } else if (!segment.equals(".")) {
            pathStack.push(segment); // Add the segment to the path
        }
    }

    // Build the final path from the stack
    StringBuilder result = new StringBuilder();
    for (String segment : pathStack) {
        if (result.length() > 0) {
            result.append("/");
        }
        result.append(segment);
    }

    return result.toString();
}

